-- | The kernel differential check against the reference implementation.
--
-- @differential/kernel_corpus.json@ is generated by
-- @differential/kernel_corpus.py@ from the pinned Python reference: seeded
-- random nets (carried as canonical Net definition v3 text), initial
-- markings, and scripts of Instance actions. For every action the corpus
-- records what the reference answered; this spec drives the Haskell
-- 'Instance' through the same script and compares every recorded value —
-- candidate bindings, firing outcomes, refusals (exception class and exact
-- message), markings, statuses, watermarks, pending maturations, and the
-- complete encoded schema-5 History — by canonical JSON spelling, so an
-- int/float difference is a failure too.
module Petrus.Impetus.KernelDifferentialSpec (spec, kernelCases, startCase, perform) where

import Control.Monad (forM_, unless, zipWithM_)
import Data.ByteString qualified as BS
import Data.Map.Strict qualified as Map
import Data.Text (Text)
import Data.Text qualified as T
import Petrus.Impetus.Binding (BoundHandler (..), Handler, handlerTokens)
import Petrus.Impetus.History (Record (RTimerMatured))
import Petrus.Impetus.History.Codec (encodeRecord)
import Petrus.Impetus.HistoryStore qualified as Store
import Petrus.Impetus.Instance
import Petrus.Impetus.NetDefinition (compileNetDefinition, parseNetDefinitionText)
import Petrus.Impetus.Petrinet hiding (candidates, nextMaturation, outputs, token)
import Petrus.Impetus.TestSupport (np)
import Petrus.Impetus.WireSupport (findExisting)
import Petrus.Json
import Test.Hspec hiding (context, pending)

spec :: Spec
spec = describe "Petrus.Impetus.Instance differential corpus" $ do
  cases <- runIO kernelCases
  it "carries the generated cases" $ length cases `shouldSatisfy` (>= 200)
  forM_ cases $ \c -> it (T.unpack (text (member "name" c))) (replayCase c)

-- | The committed corpus's cases.
kernelCases :: IO [Json]
kernelCases = do
  path <- findExisting ["differential/kernel_corpus.json", "packages/petrus-impetus/differential/kernel_corpus.json"]
  raw <- BS.readFile path
  pure $ case parseJson surrogateRefusingLoads raw of
    Right corpus | Array xs <- member "cases" corpus -> xs
    Right _ -> error "kernel corpus: no cases"
    Left problem -> error ("kernel corpus: " <> problem)

replayCase :: Json -> Expectation
replayCase c = do
  (_, inst) <- startCase c
  forM_ (zip [0 :: Int ..] (array (member "walk" c))) $ \(index, stepJson) -> do
    let action = member "action" stepJson
        context field = T.unpack (text (member "name" c)) <> " step " <> show index <> " " <> field
    candidatesBefore <- candidates inst
    same (context "candidatesBefore") (Array (map encodeBinding candidatesBefore)) (member "candidatesBefore" stepJson)
    answer <- perform inst action
    forM_ answer $ \(field, value) -> same (context (T.unpack field)) value (member field stepJson)
    current <- marking inst
    same (context "markingAfter") (encodeMarking current) (member "markingAfter" stepJson)
    current' <- status inst
    same (context "statusAfter") (String (statusText current')) (member "statusAfter" stepJson)
    w <- watermark inst
    same (context "watermarkAfter") (numberJson w) (member "watermarkAfter" stepJson)
    pending <- nextMaturation inst
    same (context "nextMaturationAfter") (maybe Null numberJson pending) (member "nextMaturationAfter" stepJson)
  history <- Store.records (instanceHistory inst)
  let expected = array (member "history" c)
  length history `shouldBe` length expected
  zipWithM_ (\i (r, e) -> same ("history record " <> show i) (encodeRecord r) e) [0 :: Int ..] (zip history expected)

-- | A case's net (compiled from its canonical definition) and a fresh
-- Instance over it, configured as the generator configured the reference.
startCase :: Json -> IO (Net, Instance)
startCase c = do
  definition <- either (fail . T.unpack) pure (parseNetDefinitionText (text (member "definition" c)))
  net <- either (fail . T.unpack) pure (compileNetDefinition definition)
  let initial = markingFromList [(np (text (member "place" e)), map decodeToken (array (member "tokens" e))) | e <- array (member "initialMarking" c)]
      uses predicate = predicate net
      config =
        defaultInstanceConfig
          { initialMarking = initial
          , guardImplementations = Map.fromList [(Symbol "small_total", smallTotal)]
          , handlerImplementations = if uses usesHandler then Map.fromList [(Symbol "tag", PureHandler tag)] else Map.empty
          , filterImplementations = if uses usesFilter then Map.fromList [(Symbol "even", even')] else Map.empty
          , suppliedIdentity = Just (text (member "name" c))
          }
  inst <- newInstance net config >>= either (fail . T.unpack . renderInstanceError) pure
  pure (net, inst)

-- | Run one scripted action; answer the fields the corpus records for it.
perform :: Instance -> Json -> IO [(Text, Json)]
perform inst action = do
  let at = instantOf (member "at" action)
  case text (member "kind" action) of
    "step" -> answered (step inst at) (\o -> [("outcome", maybe Null encodeOutcome o)])
    "deliver" -> do
      let source = np (text (member "source" action))
          tokens = map decodeToken (array (member "tokens" action))
      acceptDelivery inst source tokens (text (member "identity" action)) Nothing at >>= \case
        Left e -> pure (refusal e)
        Right (DeliveryPrior prior) -> pure [("prior", Int (fromIntegral prior.occurrence))]
        Right (DeliveryScoped _) -> fail "unexpected scoped acknowledgement"
        Right (DeliveryAccepted accepted) -> answered (completeDelivery inst accepted at) (\o -> [("outcome", encodeOutcome o)])
    "seal" -> answered (seal inst (np (text (member "source" action))) at) (const [("outcome", Null)])
    "wake" -> case at of
      Just instant -> answered (wake inst instant) (\m -> [("matured", maybe Null (encodeRecord . RTimerMatured) m)])
      Nothing -> fail "wake without an instant"
    other -> fail ("unknown action " <> T.unpack other)
  where
    answered door render = either refusal render <$> door

-- | A refusal, spelled as the reference's exception class and message.
refusal :: InstanceError -> [(Text, Json)]
refusal = \case
  Refused message -> [("error", String "ValueError"), ("message", String message)]
  TypeRefused message -> [("error", String "TypeError"), ("message", String message)]
  other -> [("error", String "unexpected"), ("message", String (renderInstanceError other))]

-- The named implementations, exact twins of the generator's Python ones.

numberOf :: Json -> Maybe Double
numberOf payload = case lookupMember "n" payload of
  Just (Int n) -> Just (fromIntegral n)
  Just (Float n) -> Just n
  _ -> Nothing

-- | @int(n) % 2 == 0@: Python's @int@ truncates toward zero.
even' :: Filter
even' token = Right (maybe False (\n -> even (truncate n :: Integer)) (numberOf token.payload))

smallTotal :: Guard
smallTotal binding = Right (sum [n | Just n <- map (numberOf . (.payload)) (bindingPeeked binding)] < 10)

-- | Route every forwarded token to every output arc, marking dict data as seen.
tag :: Handler
tag binding outputs =
  Right (handlerTokens (merge [(o.target, [routed o t]) | o <- outputs, t <- bindingTokens binding]))
  where
    routed o t = Token (maybe t.color Just o.color) (seen t.payload)
    seen = \case
      Object fields
        | any ((== "seen") . fst) fields -> Object [(k, if k == "seen" then Bool True else v) | (k, v) <- fields]
        | otherwise -> Object (fields <> [("seen", Bool True)])
      other -> other
    merge = foldl (\acc (k, v) -> if any ((== k) . fst) acc then [(k', if k' == k then vs <> v else vs) | (k', vs) <- acc] else acc <> [(k, v)]) []

usesHandler :: Net -> Bool
usesHandler net = any (\t -> t.handler /= Nothing) (netTransitions net)

usesFilter :: Net -> Bool
usesFilter net = any (\a -> a.filter /= Nothing) (netArcs net)

-- Encodings, mirroring the generator's.

encodeToken :: Token -> Json
encodeToken t = Object [("color", maybe Null String t.color), ("data", t.payload)]

decodeToken :: Json -> Token
decodeToken j = Token (case member "color" j of String s -> Just s; _ -> Nothing) (member "data" j)

encodeSelections :: [(NetPath, [Token])] -> Json
encodeSelections xs = Array [Object [("place", String (netPathText p)), ("tokens", Array (map encodeToken ts))] | (p, ts) <- xs]

encodeBinding :: Binding -> Json
encodeBinding b =
  Object
    [ ("transition", String (netPathText b.transition))
    , ("consumed", encodeSelections b.consumed)
    , ("read", encodeSelections b.read)
    , ("delivered", Array (map encodeToken b.delivered))
    ]

encodeMarking :: Marking -> Json
encodeMarking m = encodeSelections (Map.toAscList (Map.fromList (markingToList m)))

encodeOutcome :: FiringOutcome -> Json
encodeOutcome o =
  Object
    [ ("occurrence", Int (fromIntegral o.occurrence))
    , ("transition", String (netPathText o.transition))
    , ("consumed", Array (map encodeToken o.consumed))
    , ("produced", Array [Object [("place", String (netPathText p)), ("token", encodeToken t)] | (p, t) <- o.produced])
    ]

numberJson :: Number -> Json
numberJson = \case
  IntNumber n -> Int n
  FloatNumber d -> Float d

instantOf :: Json -> Maybe Instant
instantOf = \case
  Int n -> Just (IntNumber n)
  Float d -> Just (FloatNumber d)
  _ -> Nothing

-- Corpus access.

member :: Text -> Json -> Json
member key j = maybe (error ("kernel corpus: missing " <> T.unpack key)) id (lookupMember key j)

text :: Json -> Text
text = \case
  String s -> s
  other -> error ("kernel corpus: expected a string, got " <> show other)

array :: Json -> [Json]
array = \case
  Array xs -> xs
  other -> error ("kernel corpus: expected an array, got " <> show other)

-- | Compare by canonical spelling, so @1@ and @1.0@ differ as they do on the wire.
same :: String -> Json -> Json -> Expectation
same context actual expected = do
  let spell = either (const "<unencodable>") id . canonicalText
  unless (spell actual == spell expected) $
    expectationFailure (context <> "\n  haskell: " <> T.unpack (spell actual) <> "\n  python:  " <> T.unpack (spell expected))
